const rows = $input.all().map(r => r.json);

const today = new Date().toDateString();
const todayRows = rows.filter(r => 
  new Date(r.Timestamp).toDateString() === today
);

const stats = {
  date: today,
  total: todayRows.length,
  autoResolved: todayRows.filter(r => r['AI Response Sent'] === 'Yes').length,
  humanRequired: todayRows.filter(r => r['Human Required'] === 'Yes').length,
  high: todayRows.filter(r => r['Priority'] === 'high').length,
  medium: todayRows.filter(r => r['Priority'] === 'medium').length,
  low: todayRows.filter(r => r['Priority'] === 'low').length,
  automationRate: todayRows.length > 0 
    ? Math.round((todayRows.filter(r => r['AI Response Sent'] === 'Yes').length / todayRows.length) * 100) + '%' 
    : '0%'
};

return [{ json: stats }];

